def kosaraju_scc(v: int, adj: list[list[int]]) -> int:
    stack = []
    visited = [False] * v
    def dfs1(node):
        visited[node] = True
        for neighbor in adj[node]:
            if not visited[neighbor]:
                dfs1(neighbor)
        stack.append(node)
    for i in range(v):
        if not visited[i]:
            dfs1(i)
    rev_adj = [[] for _ in range(v)]
    for i in range(v):
        for j in adj[i]:
            rev_adj[j].append(i)
    visited = [False] * v
    def dfs2(node):
        visited[node] = True
        for neighbor in rev_adj[node]:
            if not visited[neighbor]:
                dfs2(neighbor)
    scc_count = 0
    while stack:
        node = stack.pop()
        if not visited[node]:
            dfs2(node)
            scc_count += 1
    return scc_count
